@CrossOrigin
@RestController
@RequestMapping("/DependentQuery")
public class DependentQueryRestController extends BaseSpringRestController {
	
	public DependentQueryRestController( DependentService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Dependent using a UUID
     * @param		UUID dependentId
     * @return		Dependent
     */    
    @GetMapping("/load")
    public Dependent load( @RequestParam(required=true) UUID dependentId ) {
    	Dependent entity = null;

    	try {  
    		entity = service.getDependent( new DependentFetchOneSummary( dependentId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Dependent using Id " + dependentId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Dependent business objects
     * @return		Set<Dependent>
     */
    @GetMapping("/")
    public List<Dependent> loadAll() {                
    	List<Dependent> dependentList = null;
        
    	try {
            // load the Dependent
            dependentList = service.getAllDependent();
            
            if ( dependentList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Dependents" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Dependents ", exc );
        	return null;
        }

        return dependentList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Dependent dependent = null;
    protected DependentService service = null;
    private static final Logger LOGGER = Logger.getLogger(DependentQueryRestController.class.getName());
    
}
